package br.com.sussmartcare.clinicalquery.adapters.in.rest; import br.com.sussmartcare.clinicalquery.application.*; import java.util.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/clinical-view") public class ClinicalQueryController {private final ClinicalQueryService app;public ClinicalQueryController(ClinicalQueryService a){app=a;}@GetMapping("/visits/{visitId}")public ClinicalPatientViewSnapshot get(@PathVariable UUID visitId){return app.get(visitId);}}
